window.kbPageData["views/entry/k-0d26ab22b6fb990e"] = {"key":"entry/k-0d26ab22b6fb990e","state":{"route":"entry/k-0d26ab22b6fb990e"},"node":{"id":"k-0d26ab22b6fb990e","mode":"k","title":"《中华人民共和国仲裁法》（新修订）","type":"事实与事件","domain":"法律","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["law"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["法律"],"时间索引":["年度事件或数据"],"来源主题":["重要法律"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"《中华人民共和国仲裁法》（新修订）","slug":"8467e061aec7"}],"directorySummary":"考点八 《中华人民共和国仲裁法》（新修订）\n2026 年全面修订，自 2026 年 3 月 1 日起施行。民商事纠纷当事人自愿达成仲裁协议，提交仲\n裁委员会裁决并受其约束的制度。可仲裁范围：平等主体的自然人、法人、非法人组织之间的\n合同纠纷和其他财产权益纠纷；不可仲裁：婚姻、收养、监护、扶养、继承等…","sources":[{"id":"0e77f0cfe607bc8e","label":"《中华人民共和国仲裁法》（新修订）","topic":"重要法律","category":"时政","text":"考点八 《中华人民共和国仲裁法》（新修订）\n2026 年全面修订，自 2026 年 3 月 1 日起施行。民商事纠纷当事人自愿达成仲裁协议，提交仲\n裁委员会裁决并受其约束的制度。可仲裁范围：平等主体的自然人、法人、非法人组织之间的\n合同纠纷和其他财产权益纠纷；不可仲裁：婚姻、收养、监护、扶养、继承等身份纠纷及依法\n应由行政机关处理的行政争议。\n仲裁机构不按行政区划层层设立，不实行级别管辖和地域管辖，由当事人协议选定；实行或裁\n或审原则、一裁终局；裁决按多数仲裁员意见作出，不能形成多数时按首席仲裁员意见作出；\n支持在线仲裁。","source":{"doc":"4e539a366dce19555ccf","first":23,"last":23,"page":23,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"law","title":"法治政府与依法行政"}],"units":{"k-0d26ab22b6fb990e":[]}};
